        return outcome.plan;
    };
    let disposition = match disposition {
        ObservedCallableDisposition::Gap => FinalDisposition::Gap,
        ObservedCallableDisposition::Failure => FinalDisposition::Failure,
    };
    record(
        outcome.plan,
        disposition,
        "observed-callable-discovery",
